// "Pro Sounds": the curated list of built-in multi-sampled instruments and
// one-shots. The audio files and their key/velocity zones come from
// manifest.json (generated by scripts/sounds/build.mjs); this file adds names,
// groups and sensible starting settings.
import type { ProParams } from '../../state/types';
import manifest from './manifest.json';

export type ProGroup =
  | 'Kicks' | '808s & Bass' | 'Snares' | 'Claps & Rims' | 'Hi-Hats' | 'Open Hats & Cymbals' | 'Percussion' | 'FX'
  | 'Piano & Keys' | 'Bells & Mallets' | 'Strings' | 'Winds & Brass' | 'Synths';

export const PRO_GROUPS: ProGroup[] = [
  'Kicks', '808s & Bass', 'Snares', 'Claps & Rims', 'Hi-Hats', 'Open Hats & Cymbals', 'Percussion', 'FX',
  'Piano & Keys', 'Bells & Mallets', 'Strings', 'Winds & Brass', 'Synths',
];

export const DRUM_GROUPS: ProGroup[] = ['Kicks', 'Snares', 'Claps & Rims', 'Hi-Hats', 'Open Hats & Cymbals', 'Percussion', 'FX'];

export interface ProSound {
  id: string;
  name: string;
  group: ProGroup;
  /** plays to the end regardless of the note length (drums, FX) */
  oneShot?: boolean;
  /** stops every sound of this choke group when it plays (closed hat → open hats) */
  chokes?: string;
  /** belongs to this choke group */
  choke?: string;
  /** recorded by people (VSCO-2-CE) or synthesized for Goofy Studio */
  real?: boolean;
  /** extra search words */
  tags?: string;
  /** starting values for the instrument */
  defaults?: Partial<ProParams>;
  /** starting channel volume */
  volume?: number;
}

const kick = (id: string, name: string, tags = ''): ProSound => ({ id, name, group: 'Kicks', oneShot: true, tags, volume: 0.9 });
const snare = (id: string, name: string, tags = ''): ProSound => ({ id, name, group: 'Snares', oneShot: true, tags, volume: 0.75 });
const clap = (id: string, name: string, tags = ''): ProSound => ({ id, name, group: 'Claps & Rims', oneShot: true, tags, volume: 0.7 });
const hat = (id: string, name: string, tags = ''): ProSound => ({ id, name, group: 'Hi-Hats', oneShot: true, chokes: 'ohat', tags, volume: 0.55 });
const ohat = (id: string, name: string, tags = ''): ProSound => ({ id, name, group: 'Open Hats & Cymbals', oneShot: true, choke: 'ohat', tags, volume: 0.5, defaults: { mono: true } });
const perc = (id: string, name: string, real = false, tags = ''): ProSound => ({ id, name, group: 'Percussion', oneShot: true, real, tags, volume: 0.6 });

