const BY_ID = new Map(PRO_SOUNDS.map((s) => [s.id, s]));

export function proSound(id: string | undefined | null): ProSound | undefined {
  return id ? BY_ID.get(id) : undefined;
}

/** Zone of a multi-sample as stored in manifest.json. */
export interface ProZone {
  /** file below public/sounds/ */
  f: string;
  /** root key (MIDI) */
  r: number;
  lo: number;
  hi: number;
  /** velocity range 0..127 */
  vl: number;
  vh: number;
  /** round-robin index */
  rr?: number;
  /** loop start / end in seconds */
  ls?: number;
  le?: number;
  /** playback gain (the file was stored quieter so it does not clip) */
  g?: number;
}

const SOUNDS = (manifest as unknown as { sounds: Record<string, { zones: ProZone[]; loop?: boolean }> }).sounds;

export function proZones(id: string): ProZone[] {
  return SOUNDS[id]?.zones ?? [];
}

export function defaultPro(sound = 'keys.upright'): ProParams {
  const base: ProParams = { sound, tune: 0, attack: 0.002, release: 0.25, tone: 1, drive: 0, glide: 0, mono: false, velocity: 0.5, reverse: false, level: 0.9 };
  return { ...base, ...(proSound(sound)?.defaults ?? {}), sound };
}

// ---------------------------------------------------------------- kits

export interface KitSlot {
  name: string;
  sound: string;
  /** starter pattern: x = hit, o = soft hit, . = rest (one character per 16th) */
  steps?: string;
  /** hi-hat rolls on the starter pattern: step index → hits per step */
  rolls?: Record<number, number>;
  volume?: number;
  pan?: number;
}

export interface ProKit {
  id: string;
  name: string;
  genre: string;
  color: string;
  bpm: number;
  swing: number;
  slots: KitSlot[];
  /** starter 808 / bass line: [semitones above the key root, start step, length in steps] */
  bass?: { sound: string; notes: [number, number, number][] };
}

